    """Implements a stack with push, pop, peek, and is_empty methods."""
    def __init__(self):
        self._items = []

ground_truth_solution:
def push(self, item):
    self._items.append(item)
def pop(self):
    if not self._items: raise IndexError('pop from empty stack')
    return self._items.pop()
def peek(self):
    if not self._items: raise IndexError('peek from empty stack')
    return self._items[-1]
def is_empty(self) -> bool:
    return len(self._items) == 0
def __len__(self) -> int:
    return len(self._items)

prompt:
class BoundedCounter:
    """A counter with minimum, maximum, and step values."""
    def __init__(self, start: int = 0, min_val: int = 0, max_val: int = 100):
        self.min_val = min_val
        self.max_val = max_val
        self.val = max(min_val, min(start, max_val))

ground_truth_solution:
def increment(self, step: int = 1) -> int:
    self.val = min(self.max_val, self.val + step)
    return self.val
def decrement(self, step: int = 1) -> int:
    self.val = max(self.min_val, self.val - step)
    return self.val
def reset(self):
    self.val = self.min_val
    return self.val

