def count(self) -> int:
    return len(self._vals)
def mean(self) -> float:
    if not self._vals: return 0.0
    return sum(self._vals) / len(self._vals)
def min(self) -> float:
    if not self._vals: raise ValueError()
    return min(self._vals)
def max(self) -> float:
    if not self._vals: raise ValueError()
    return max(self._vals)

